WITH valid AS (SELECT *, DAYOFWEEK(last_restock) AS last_restock_dayofweek, CASE WHEN quantity >= 261 THEN 'High' WHEN quantity >= 110 THEN 'Medium' ELSE 'Low' END AS quantity_band FROM inventory WHERE last_restock > DATE '2023-07-06' AND last_restock < '2024-09-30'), with_windows AS (SELECT id, store_id, product_id, quantity_band, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity, id) AS event_seq, STDDEV_SAMP(last_restock_dayofweek) OVER (PARTITION BY product_id) AS product_id_stddev_samp_last_restock_dayofweek, COUNT(last_restock_dayofweek) OVER (PARTITION BY store_id) AS store_id_count_last_restock_dayofweek, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY last_restock_dayofweek DESC, id) AS event_seq_2, SUM(last_restock_dayofweek) OVER (PARTITION BY product_id ORDER BY last_restock_dayofweek, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_last_restock_dayofweek FROM valid), scored AS (SELECT *, DENSE_RANK() OVER w_ordered AS event_seq_2_dense_rank, ROUND(store_id_count_last_restock_dayofweek / SUM(store_id_count_last_restock_dayofweek) OVER (PARTITION BY store_id, product_id), 4) AS store_id_count_last_restock_dayofweek_share FROM with_windows WHERE product_id IN (1, 5) WINDOW w_ordered AS (PARTITION BY product_id, store_id ORDER BY event_seq_2 DESC NULLS LAST)), cleaned AS (SELECT id, store_id, product_id, quantity_band, event_seq, product_id_stddev_samp_last_restock_dayofweek, store_id_count_last_restock_dayofweek, running_last_restock_dayofweek, event_seq_2_dense_rank, store_id_count_last_restock_dayofweek_share, ROUND(product_id_stddev_samp_last_restock_dayofweek * 1.1, 2) AS product_id_stddev_samp_last_restock_dayofweek_scaled FROM scored WHERE event_seq > 4), joined AS (SELECT a.*, p.store_name FROM cleaned a LEFT JOIN stores p ON a.store_id = p.id), filtered AS (SELECT id, quantity_band, event_seq, product_id_stddev_samp_last_restock_dayofweek, store_id_count_last_restock_dayofweek, running_last_restock_dayofweek, store_id_count_last_restock_dayofweek_share, product_id_stddev_samp_last_restock_dayofweek_scaled, store_name, REGEXP_REPLACE(store_name, ' ', '_') AS store_name_slug FROM joined WHERE store_name IS NOT NULL), scored_inventory AS (SELECT *, COUNT(event_seq) OVER w_grp AS last4_count_event_seq, MIN(event_seq) OVER w_grp AS last4_min_event_seq, MAX(event_seq) OVER w_grp AS last4_max_event_seq FROM filtered WINDOW w_grp AS (ORDER BY event_seq, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)) SELECT id, quantity_band, event_seq, product_id_stddev_samp_last_restock_dayofweek, store_id_count_last_restock_dayofweek, store_name, store_name_slug, last4_min_event_seq FROM scored_inventory ORDER BY event_seq NULLS FIRST
